function startBoss(){state.bossActive=true;state.bossMax=8+state.bossCycle*5+(state.baseLevel-1)*3;state.bossHP=state.bossMax;state.bossTimeLeft=15;state.nextBossAt=state.mission+4;render();notify('CHEFE NA CIDADE! DEFENDA A BASE!');popText('BOSS!',window.innerWidth*.34,window.innerHeight*.36,true);save()}
function finishBoss(won){state.bossActive=false;state.bossTimeLeft=0;if(won){const reward=Math.round((35+passive()*8)*(1+state.bossCycle*.35));state.credits+=reward;state.totalEarned+=reward;state.baseLevel++;state.bossCycle++;notify(`BOSS DERROTADO! BASE EVOLUIU PARA NÍVEL ${state.baseLevel}!`);popText('POW! +'+compact(reward),window.innerWidth*.35,window.innerHeight*.4,true)}else{state.nextBossAt=state.mission+4;notify('O BOSS ESCAPOU! ELE VOLTARÁ — PREPARE-SE!')}render();save()}
function collect(){const now=Date.now();state.lastClick=now;const btn=$('alertButton'),rect=btn.getBoundingClientRect();if(state.bossActive){state.bossHP=Math.max(0,state.bossHP-clickPower());popText('👊 -'+compact(clickPower()),rect.left+rect.width*(.3+Math.random()*.4),rect.top-8,true);$('city').classList.remove('shake');void $('city').offsetWidth;$('city').classList.add('shake');if(state.bossHP<=0)finishBoss(true);else render();return}if(now-state.lastClick<900)state.combo=Math.min(20,state.combo+1);else state.combo=0;const comboMultiplier=Math.min(5,1+Math.floor(state.combo/5));const amount=clickPower()*comboMultiplier;state.credits+=amount;state.totalEarned+=amount;popText(state.combo>0&&state.combo%5===0?'👊 POW!':`👊 +${compact(amount)}`,rect.left+rect.width*(.3+Math.random()*.4),rect.top-8,true);$('city').classList.remove('shake');void $('city').offsetWidth;$('city').classList.add('shake');render();}

